#include "Internal.h"
#include "../../Sources/AtomicImageWriter.h"
namespace RetroMediaLab::MediaEngine::CpcDsk {
namespace {
std::vector<std::uint8_t> trackBytes(const Track& track,std::size_t trackPosition,ContainerKind kind,std::stop_token token){
    using namespace Constants;checkCancellation(token);if(track.index<0||std::uint64_t(track.index)!=trackPosition)throw MediaError(DiagnosticCode::CpcDskTrackIndex,{std::to_string(track.index),std::to_string(trackPosition)});if(!track.present){if(kind==ContainerKind::Standard)throw MediaError(DiagnosticCode::CpcDskStandardRepresentation,{std::to_string(track.index)});return {};}
    if(track.sectors.size()>MaximumSectorsPerTrack)throw MediaError(DiagnosticCode::CpcDskTooManySectors,{std::to_string(track.index)});std::size_t unpadded=TrackInformationBlockSize;for(const auto& sector:track.sectors){if(sector.data.size()>MaximumBuffer-unpadded)throw MediaError(DiagnosticCode::CpcDskOverflow);unpadded+=sector.data.size();}
    if(kind==ContainerKind::Extended&&unpadded>MaximumBuffer-(ExtendedTrackSizeUnit-1))throw MediaError(DiagnosticCode::CpcDskOverflow);const auto size=kind==ContainerKind::Extended?(unpadded+ExtendedTrackSizeUnit-1)/ExtendedTrackSizeUnit*ExtendedTrackSizeUnit:unpadded;if(kind==ContainerKind::Extended&&size/ExtendedTrackSizeUnit>std::numeric_limits<std::uint8_t>::max())throw MediaError(DiagnosticCode::CpcDskExtendedLarge,{std::to_string(track.index),std::to_string(size)});
    std::vector<std::uint8_t> bytes(size);std::copy(TrackHeader.begin(),TrackHeader.end(),bytes.begin());bytes[TrackCylinderOffset]=track.cylinder;bytes[TrackHeadOffset]=track.head;bytes[TrackSectorSizeCodeOffset]=track.sectorSizeCode;bytes[TrackSectorCountOffset]=std::uint8_t(track.sectors.size());bytes[TrackGap3LengthOffset]=track.gap3Length;bytes[TrackFillerByteOffset]=track.fillerByte;std::size_t position=TrackInformationBlockSize;
    for(std::size_t index=0;index<track.sectors.size();++index){checkCancellation(token);const auto& sector=track.sectors[index];if(kind==ContainerKind::Standard&&sector.data.size()!=Internal::nominalSize(sector.sizeCode))throw MediaError(DiagnosticCode::CpcDskStandardRepresentation,{std::to_string(track.index)});const auto descriptor=SectorDescriptorTableOffset+index*SectorDescriptorSize;bytes[descriptor+SectorCylinderOffset]=sector.cylinder;bytes[descriptor+SectorHeadOffset]=sector.head;bytes[descriptor+SectorIdOffset]=sector.id;bytes[descriptor+SectorSizeCodeOffset]=sector.sizeCode;bytes[descriptor+SectorStatus1Offset]=sector.status1;bytes[descriptor+SectorStatus2Offset]=sector.status2;if(kind==ContainerKind::Extended)Internal::word(bytes,descriptor+SectorStoredSizeOffset,std::uint16_t(sector.data.size()));std::copy(sector.data.begin(),sector.data.end(),bytes.begin()+position);position+=sector.data.size();}
    return bytes;
}
}
std::vector<std::uint8_t> build(const Image& image,std::stop_token token){
    using namespace Constants;const auto count=std::size_t(image.cylinders)*image.heads;if(image.cylinders<MinimumCylinderCount||image.cylinders>MaximumCylinderCount||image.heads<MinimumHeadCount||image.heads>MaximumHeadCount||image.tracks.size()!=count)throw MediaError(DiagnosticCode::CpcDskTrackCollection);
    std::vector<std::vector<std::uint8_t>> serialized;serialized.reserve(count);std::size_t total=DiskInformationBlockSize;for(std::size_t index=0;index<count;++index){auto bytes=trackBytes(image.tracks[index],index,image.kind,token);if(bytes.size()>MaximumBuffer-total)throw MediaError(DiagnosticCode::CpcDskOverflow);total+=bytes.size();serialized.push_back(std::move(bytes));}
    if(image.kind==ContainerKind::Standard){const auto size=serialized.front().size();if(size>std::numeric_limits<std::uint16_t>::max()||std::any_of(serialized.begin(),serialized.end(),[&](const auto& track){return track.size()!=size;}))throw MediaError(DiagnosticCode::CpcDskUniformTracks);}
    if(image.kind!=ContainerKind::Standard&&ExtendedTrackSizeTableOffset+count>DiskInformationBlockSize)throw MediaError(DiagnosticCode::CpcDskExtendedTable,{std::to_string(DiskInformationBlockSize-ExtendedTrackSizeTableOffset)});
    std::vector<std::uint8_t> bytes(total);const auto header=image.kind==ContainerKind::Extended?ExtendedHeader:StandardHeader;std::copy(header.begin(),header.end(),bytes.begin());std::copy(Creator.begin(),Creator.end(),bytes.begin()+CreatorOffset);bytes[CylinderCountOffset]=image.cylinders;bytes[HeadCountOffset]=image.heads;
    if(image.kind==ContainerKind::Standard)Internal::word(bytes,StandardTrackSizeOffset,std::uint16_t(serialized.front().size()));else for(std::size_t index=0;index<count;++index){const auto units=serialized[index].size()/ExtendedTrackSizeUnit;if(units>std::numeric_limits<std::uint8_t>::max())throw MediaError(DiagnosticCode::CpcDskOverflow);bytes[ExtendedTrackSizeTableOffset+index]=std::uint8_t(units);}
    std::size_t position=DiskInformationBlockSize;for(const auto& track:serialized){std::copy(track.begin(),track.end(),bytes.begin()+position);position+=track.size();}return bytes;
}
void write(const Image& image,const std::filesystem::path& path,std::stop_token token){const auto bytes=build(image,token);writeAtomicImage(path,[&](const ImageOutput& output,std::stop_token current){checkCancellation(current);output(bytes);},token);}
}
